import * as T from 'three';
import {clothLocalPoint} from './cloth-config.js';
export function buildCloth(group,p,own){const count=p.columns*p.rows,positions=new Float32Array(count*3),uv=new Float32Array(count*2),indices=new Uint32Array((p.columns-1)*(p.rows-1)*6),point=new T.Vector3();for(let i=0;i<count;i++){clothLocalPoint(p,i,point).toArray(positions,i*3);uv[i*2]=Math.floor(i/p.rows)/(p.columns-1);uv[i*2+1]=1-(i%p.rows)/(p.rows-1);}let at=0;for(let u=0;u<p.columns-1;u++)for(let v=0;v<p.rows-1;v++){const a=u*p.rows+v,b=a+p.rows;indices.set([a,b,b+1,a,b+1,a+1],at);at+=6;}const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.BufferAttribute(positions,3).setUsage(T.DynamicDrawUsage));geometry.setAttribute('uv',new T.BufferAttribute(uv,2));geometry.setIndex(new T.BufferAttribute(indices,1));geometry.computeVertexNormals();geometry.attributes.normal.setUsage(T.DynamicDrawUsage);const material=new T.MeshStandardMaterial({color:0x8dacc4,roughness:.8,side:T.DoubleSide}),mesh=new T.Mesh(geometry,material);mesh.userData.cloth=true;mesh.userData.hbMotionVectors='perVertex';own(group,geometry);own(group,material);group.add(mesh);group.userData.clothMesh={mesh,geometry,rest:positions.slice(),version:-1,point,inverse:new T.Matrix4()};}
export function updateCloth(group,running){const state=group.userData.clothMesh;if(!state)return;const frame=running?group.userData.clothFrame:null,version=frame?.version??-1;if(state.version===version&&state.generation===frame?.generation)return;const geometry=state.geometry,positions=geometry.attributes.position.array;if(frame){if(frame.positions.length!==positions.length)return;state.inverse.copy(group.matrixWorld).invert();for(let i=0;i<positions.length;i+=3)state.point.fromArray(frame.positions,i).applyMatrix4(state.inverse).toArray(positions,i);}else positions.set(state.rest);state.version=version;state.generation=frame?.generation;geometry.attributes.position.needsUpdate=true;geometry.computeVertexNormals();geometry.computeBoundingSphere();geometry.computeBoundingBox();}
